class _ShadowSignal(_Signal):

    __slots__ = ('_waiter',)

    def __init__(self, val):
        _Signal.__init__(self, val)
        # self._driven = True # set this in conversion analyzer

    # remove next attribute assignment
    @_Signal.next.setter
