                          "use `amaranth.lib.scheduler.RoundRobin`; note that RoundRobin does not "
                          "require a policy anymore but to get the same behavior as SP_CE you"
                          "should use an EnableInserter",
                          DeprecationWarning, stacklevel=1)
            self.ce = Signal()
