                          "use `amaranth.lib.scheduler.RoundRobin`; note that RoundRobin does not "
                          "require a policy anymore",
                          DeprecationWarning, stacklevel=1)

        ###

        if n > 1:
            cases = {}
            for i in range(n):
                switch = []
                for j in reversed(range(i+1, i+n)):
                    t = j % n
                    switch = [
                        If(self.request[t],
                            self.grant.eq(t)
                        ).Else(
                            *switch
