        offset = Value.cast(offset)
        if offset.shape().signed:
            raise TypeError("Part offset must be unsigned")

super().__init__(src_loc_at=src_loc_at)
        self.value  = value
        self.offset = offset
        self.width  = width
        self.stride = stride

