        def mask(value):
            value_mask = (1 << len(value)) - 1
            return f"({value_mask:#x} & {self(value)})"

        def sign(value):
            if value.shape().signed:
                return f"sign({mask(value)}, {-1 << (len(value) - 1):#x})"
            else: # unsigned
                return mask(value)

