# {component_name}
#-------------------------------------------------------------------------

class {component_name}( Component ):
  id_ = 0

  def __init__( s, *args, **kwargs ):
    s._finalization_count = 0

    # initialize FFI, define the exposed interface
    s.ffi = FFI()
    s.ffi.cdef("""
      typedef struct {{

        // Exposed port interface
{port_cdefs}

        // Verilator model
        void * _cffi_model;

        // Verilator simulation context
        void * _cffi_context_ptr;

        // VCD state
        int _cffi_vcd_en;

        // VCD tracing helpers
        void *       _cffi_tfp;
        unsigned int _cffi_trace_time;

        // Verilog line trace buffer
        char _cffi_line_trace_str[512];

      }} V{component_name}_t;

      V{component_name}_t * V{component_name}_create_model( const char * );
      void V{component_name}_destroy_model( V{component_name}_t *);
      void V{component_name}_comb_eval( V{component_name}_t * );
      void V{component_name}_seq_eval( V{component_name}_t * );
      void V{component_name}_assert_on( V{component_name}_t *, bool );
      bool V{component_name}_has_assert_fired( V{component_name}_t * );
      {trace_c_def}

    """)

    # Print the modification time stamp of the shared lib
    # print('Modification time of {{}}: {{}}'.format(
    #       '{lib_file}', os.path.getmtime( './{lib_file}' ) ))

    # Import the shared library containing the model. We defer
    # construction to the elaborate_logic function to allow the user to
    # set the vcd_file.
    # NOTE: the RTLD_NODELETE flag is necessary in this dlopen() to make sure
    # all loaded shared libraries stick to the current processes (i.e., cannot
    # be unloaded) until the exit of the main process. This behavior is necessary
    # to avoid segfaults at exits due to destruction of thread-local variables,
    # which are heavily used in Verilator's runtime library.
    s._ffi_inst = s.ffi.dlopen('./{lib_file}', s.ffi.RTLD_NODELETE | s.ffi.RTLD_NOW)

    # increment instance count
    {component_name}.id_ += 1

  def finalize( s ):
    """Finalize the imported component.

# Buffer for line tracing
    s._convert_string = s.ffi.string

    # Use non-attribute varialbe to reduce CPython bytecode count
    _ffi_m = s._ffi_m
    _ffi_inst_comb_eval = s._ffi_inst.V{component_name}_comb_eval
    _ffi_inst_seq_eval  = s._ffi_inst.V{component_name}_seq_eval

    # declare the port interface
{port_defs}

    # update blocks that converts ffi interface to/from pymtl ports
{structs_input}
{structs_output}

    @update
    def comb_upblk():

      # Set inputs
{set_comb_input}

      _ffi_inst_comb_eval( _ffi_m )

      # Write all outputs
{set_comb_output}

    @update_ff
    def seq_upblk():
      # seq_eval will automatically tick clock in C land
      _ffi_inst_seq_eval( _ffi_m )

      if s._ffi_inst.V{component_name}_has_assert_fired( _ffi_m ):
        raise AssertionError("A Verilog assertion fired in the Verilator simulation!")

  def assert_on( s, enable ):
    assert isinstance( enable, bool )
    s._ffi_inst.V{component_name}_assert_on( s._ffi_m, enable )

  def line_trace( s ):
    if {external_trace}:
      s._ffi_inst.V{component_name}_line_trace( s._ffi_m, s._ffi_m._cffi_line_trace_str )
      return s._convert_string( s._ffi_m._cffi_line_trace_str ).decode('ascii')
    else:
{line_trace}

  def internal_line_trace( s ):
{in_line_trace}
'''

def setup_configs( s, m, tr_pass, ph_pass ):
    # VerilatorImportConfigs alone does not have the complete information about
    # the module to be imported. For example, we need to read from the placeholder
    # configuration to figure out the pickled file name and the top module name.
    # This method is meant to be called before calling other public APIs.

    s.translated_top_module = m.get_metadata( tr_pass.translated_top_module )
    s.translated_source_file = m.get_metadata( tr_pass.translated_filename )

    ph_cfg = m.get_metadata( ph_pass.placeholder_config )
    s.verilog_hash = get_hash_of_lean_verilog( s.translated_source_file )
    s.v_include = ph_cfg.v_include
    s.v_libs = ph_cfg.v_libs
    s.src_file = ph_cfg.src_file
    s.port_map = ph_cfg.port_map
    s.params = ph_cfg.params

    # Infer vl_line_trace by scanning through the source file
    try:
      trim = lambda s: ''.join(s.split())
      if not s.vl_line_trace:
        with open(s.src_file) as fd:
          for line in fd.readlines():
            if "`VC_TRACE_BEGIN" in trim(line):
              s.vl_line_trace = True
              break
    except OSError:
      pass

    if not s.vl_mk_dir:
      s.vl_mk_dir = f'obj_dir_{s.translated_top_module}'

  def get_vl_xinit_value( s ):
    if s.vl_xinit == 'zeros':
      return 0
    elif s.vl_xinit == 'ones':
      return 1
    elif ( s.vl_xinit == 'rand' ) or isinstance( s.vl_xinit, int ):
      return 2
    else:
      raise InvalidPassOptionValue("vl_xinit should be an int or one of 'zeros', 'ones', or 'rand'!")

  def get_vl_xinit_seed( s ):
    if isinstance( s.vl_xinit, int ):
      return s.vl_xinit
    else:
      return 0

  def get_c_wrapper_path( s ):
    return f'{s.translated_top_module}_v.cpp'

  def get_py_wrapper_path( s ):
    return f'{s.translated_top_module}_v.py'

  def get_shared_lib_path( s ):
    return f'lib{s.translated_top_module}_v.so'

