class StructInst( BaseBehavioralRTLIR ):
  def __init__( s, struct, values ):
    s.struct = struct
    s.values = values

  def __eq__( s, other ):
    if not isinstance(other, StructInst) or s.struct != other.struct:
      return False
    for x, y in zip( s.values, other.values ):
      if x != y:
        return False
    return True

