    """Return the behavioral RTLIR of function node.

nbits = s.const_extractor.enter( node.args[1] )
      if isinstance(nbits, type) and issubclass( nbits, Bits ):
        nbits = nbits.nbits
      if not isinstance( nbits, int ):
