class ConstantExtractor( ast.NodeVisitor ):
  def __init__( s, blk, global_ns, closure_ns ):
    s.blk = blk
    s.globals = global_ns
    s.cache = {}
    s.closure = closure_ns
    s.pymtl_functions = { concat, sext, zext, trunc,
                          reduce_or, reduce_and, reduce_xor,
                          copy.copy, copy.deepcopy }

    if sys.version_info < (3,8,10000):
      s.visit_Subscript = s._visit_Subscript_up_to_py38
    else:
      s.visit_Subscript = s._visit_Subscript_starting_py39

  def generic_visit( s, node ):
    return None

  def enter( s, node ):
    ret = s.visit( node )
    # Constant objects that are recognized
    # 1. int, BitsN( X )
    # 2. BitsN
    # 3. BitStruct, BitStruct()
    # 4. Functions, including concat, zext, sext, etc.
    is_value = isinstance(ret, (int, Bits)) or is_bitstruct_inst(ret)
    is_type = isinstance(ret, type) and (issubclass(ret, Bits) or is_bitstruct_class(ret))
    try:
      is_function = ret in s.pymtl_functions
    except:
      is_function = False

    if is_value or is_type or is_function:
      return ret
    else:
      return None

  def visit_Attribute( s, node ):
    if node in s.cache:
      return s.cache[node]
    value = s.visit( node.value )
    try:
      ret = getattr( value, node.attr )
    except AttributeError:
      ret = None
    s.cache[node] = ret
    return ret

  def _visit_Subscript_up_to_py38( s, node ):
    if node in s.cache:
      return s.cache[node]
    ret = None
    if isinstance( node.slice, ast.Index ):
      value = s.visit( node.value )
      idx = s.visit( node.slice )
      if value is not None and idx is not None:
        try:
          ret = value[idx]
        except:
          ret = None
    s.cache[node] = ret
    return ret

def _visit_Subscript_starting_py39( s, node ):
    if node in s.cache:
      return s.cache[node]
    ret = None
    value = s.visit( node.value )
    idx = s.visit( node.slice )
    if value is not None and idx is not None:
      try:
        ret = value[idx]
      except:
        ret = None
    s.cache[node] = ret
    return ret

  def visit_Index( s, node ):
    if node in s.cache:
      return s.cache[node]
    ret = s.visit( node.value )
    s.cache[node] = ret
    return ret

  def visit_Name( s, node ):
    name = node.id
    if name in s.closure:
      # free var from closure
      obj = s.closure[ name ]
    elif name in s.globals:
      # free var from the global name space
      obj = s.globals[ name ]
    else:
      obj = None
    return obj

  def visit_Num( s, node ):
    return node.n

  def visit_Constant( s, node ):
    return node.value

has_tmpvar = any(isinstance(n, bir.TmpVar) for n in bir_node.targets)
    all_tmpvar = all(isinstance(n, bir.TmpVar) for n in bir_node.targets)
    if has_tmpvar and not all_tmpvar:
      raise PyMTLSyntaxError( s.blk, node,
        'all targets have to be tmpvars if any target on LHS is a tmpvar!' )
    if has_tmpvar:
      return True
    else:
      return super().get_blocking(node, bir_node)

  def visit_Call( s, node ):
    obj = s.get_call_obj( node )
    # At L2 we add bool type but we do not support instantiating a bool
    # value -- that should always be the result of a comparison!
    if obj is rdt.Bool:
      raise PyMTLSyntaxError( s.blk, node,
        'bool values cannot be instantiated explicitly!' )
    return super().visit_Call( node )

  def visit_Name( s, node ):
    # temporary variable
    if (not node.id in s.closure) and (not node.id in s.globals):
      # check if is a LoopVar or not
      if node.id in s.loop_var_env:
        ret = bir.LoopVar( node.id )
      elif node.id in s.tmp_var_env:
        ret = bir.TmpVar( node.id, s._upblk_name )
      elif isinstance( node.ctx, ast.Load ):
        # trying to load an unregistered tmpvar
        raise PyMTLSyntaxError( s.blk, node,
          'tmpvar ' + node.id + ' used before assignment!' )
      else:
        # This is the first time we see this tmp var
        s.tmp_var_env.add( node.id )
        ret = bir.TmpVar( node.id, s._upblk_name )
      ret.ast = node
      return ret

    else:
      return super().visit_Name( node )

  def visit_If( s, node ):
    cond = s.visit( node.test )
    body = []
    for body_stmt in node.body:
      body.append( s.visit( body_stmt ) )
    orelse = []
    for orelse_stmt in node.orelse:
      orelse.append( s.visit( orelse_stmt ) )
    ret = bir.If( cond, body, orelse )
    ret.ast = node
    return ret

  def visit_For( s, node ):
    # First fill the loop_var, start, end, step fields
    if node.orelse != []:
      raise PyMTLSyntaxError( s.blk, node,
        "for loops cannot have 'else' branch!" )
    if not isinstance( node.target, ast.Name ):
      raise PyMTLSyntaxError( s.blk, node,
        "The loop index must be a temporary variable!" )
    loop_var_name = node.target.id

