from pymtl3 import *

class Encoder( Component ):
  def construct( s, in_nbits, out_nbits ):

    # Interface

    s.in_ =  InPort( in_nbits )
    s.out = OutPort( out_nbits )

    # Constants

    s.in_nbits  = in_nbits
    s.out_nbits = out_nbits

    # Logic

    @update
    def encode():
      s.out @= 0
      for i in range( s.in_nbits ):
        if s.in_[i]:
          s.out @= i

  def line_trace( s ):
    return "in:{:0>{n}b} | out:{}".format(
      int( s.in_ ), s.out, n=s.in_nbits
    )

from pymtl3 import *

class RegisterFile( Component ):

  def construct( s, Type, nregs=32, rd_ports=1, wr_ports=1,
                const_zero=False ):

    addr_type = mk_bits( max( 1, clog2( nregs ) ) )

    s.raddr = [ InPort( addr_type ) for i in range( rd_ports ) ]
    s.rdata = [ OutPort( Type ) for i in range( rd_ports ) ]

    s.waddr = [ InPort( addr_type ) for i in range( wr_ports ) ]
    s.wdata = [ InPort( Type ) for i in range( wr_ports ) ]
    s.wen   = [ InPort( Bits1 ) for i in range( wr_ports ) ]

    s.regs = [ Wire( Type ) for i in range(nregs) ]

    @update
    def up_rf_read():
      for i in range( rd_ports ):
        s.rdata[i] @= s.regs[ s.raddr[i] ]

    if const_zero:
      @update_ff
      def up_rf_write_constzero():
        for i in range( wr_ports ):
          if s.wen[i] & (s.waddr[i] != 0):
            s.regs[ s.waddr[i] ] <<= s.wdata[i]
    else:
      @update_ff
      def up_rf_write():
        for i in range( wr_ports ):
          if s.wen[i]:
            s.regs[ s.waddr[i] ] <<= s.wdata[i]

class RegisterFileRst( Component ):

  def construct( s, Type, nregs=32, rd_ports=1, wr_ports=1,
                const_zero=False, reset_value=0 ):

    addr_type = mk_bits( max( 1, clog2( nregs ) ) )

    s.raddr = [ InPort( addr_type ) for i in range( rd_ports ) ]
    s.rdata = [ OutPort( Type ) for i in range( rd_ports ) ]

    s.waddr = [ InPort( addr_type ) for i in range( wr_ports ) ]
    s.wdata = [ InPort( Type ) for i in range( wr_ports ) ]
    s.wen   = [ InPort( Bits1 ) for i in range( wr_ports ) ]

    s.regs = [ Wire( Type ) for i in range(nregs) ]

    @update
    def up_rf_read():
      for i in range( rd_ports ):
        s.rdata[i] @= s.regs[ s.raddr[i] ]

    if const_zero:
      @update_ff
      def up_rf_write_constzero():
        if s.reset: 
          for i in range( nregs ):
            s.regs[i] <<= reset_value
        else:
          for i in range( wr_ports ):
            if s.wen[i] & (s.waddr[i] != 0):
              s.regs[ s.waddr[i] ] <<= s.wdata[i]
    else:
      @update_ff
      def up_rf_write():      
        if s.reset: 
          for i in range( nregs ):
            s.regs[i] <<= reset_value
        else:
          for i in range( wr_ports ):
            if s.wen[i]:
              s.regs[ s.waddr[i] ] <<= s.wdata[i]

