from pymtl3 import *

def valrdy_to_str( msg, val, rdy, trace_len=15 ):
  if     val and not rdy: return "#".ljust( trace_len )
  if not val and     rdy: return " ".ljust( trace_len )
  if not val and not rdy: return ".".ljust( trace_len )
  return f"{msg}".ljust( trace_len ) # val and rdy

class IStreamIfc( Interface ):

  def construct( s, Type ):

    s.msg = InPort( Type )
    s.val = InPort()
    s.rdy = OutPort()

    if isinstance( Type, int ):
      s.trace_len = len(str(mk_bits(Type)()))
    else:
      s.trace_len = len(str(Type()))

  def __str__( s ):
    return valrdy_to_str( s.msg, s.val, s.rdy, s.trace_len )

  def line_trace( s ):
    return str( s )

class OStreamIfc( Interface ):

  def construct( s, Type ):

    s.msg = OutPort( Type )
    s.val = OutPort()
    s.rdy = InPort()

    if isinstance( Type, int ):
      s.trace_len = len(str(mk_bits(Type)()))
    else:
      s.trace_len = len(str(Type()))

  def __str__( s ):
    return valrdy_to_str( s.msg, s.val, s.rdy, s.trace_len )

  def line_trace( s ):
    return str( s )

import greenlet
from pymtl3 import *
from pymtl3.extra import clone_deepcopy
from .ifcs.ifcs import IStreamIfc

class IStreamBlockingAdapterFL( Component ):

  @blocking
  def deq( s ):
    while s.entry is None:
      greenlet.getcurrent().parent.switch(0)
    ret = s.entry
    s.entry = None
    return ret

  def construct( s, Type ):
    s.istream = IStreamIfc( Type )
    s.entry = None

    @update_once
    def up_recv_rdy():
      s.istream.rdy @= (s.entry is None)

    @update_once
    def up_recv_msg():
      if (s.entry is None) & s.istream.val:
        s.entry = clone_deepcopy( s.istream.msg )

    s.add_constraints( M( s.deq )       < U( up_recv_rdy ), # deq before recv in a cycle -- pipe behavior
                       U( up_recv_rdy ) < U( up_recv_msg ) )

  def line_trace( s ):
    return f"{s.istream}({s.entry})"

