from pymtl3 import *

class XcelMsgType:
  # TODO: figure out whether we want to use Bits1 here.
  READ  = 0
  WRITE = 1

  str = {
    READ  : "rd",
    WRITE : "wr",
  }

def mk_xcel_msg( addr, data ):
  return mk_xcel_req_msg( addr, data ), mk_xcel_resp_msg( data )

def mk_xcel_req_msg( a, d ):
  @bitstruct
  class XcelReqMsg:
    type_ : Bits1
    addr  : mk_bits( a )
    data  : mk_bits( d )

    def __str__( self ):
      return "{}:{}:{}".format(
        XcelMsgType.str[ int(self.type_) ],
        self.addr,
        self.data if self.type_ != XcelMsgType.READ else " " * ( d//4 ),
      )

  return XcelReqMsg

def mk_xcel_resp_msg( d ):
  @bitstruct
  class XcelRespMsg:
    type_ : Bits1
    data  : mk_bits( d )

    def __str__( self ):
      return "{}:{}".format(
        XcelMsgType.str[ int(self.type_) ],
        self.data if self.type_ != XcelMsgType.WRITE else " " * ( d//4 ),
      )

  return XcelRespMsg

import greenlet

from pymtl3 import *
from pymtl3.extra import clone_deepcopy
from pymtl3.stdlib.reqresp.ifcs import RequesterIfc

class XcelRequesterAdapterFL( Component ):

  @blocking
  def read( s, addr ):
    while s.req_entry is not None:
      greenlet.getcurrent().parent.switch(0)

    s.req_entry = s.create_req( 0, addr )

    while s.resp_entry is None:
      greenlet.getcurrent().parent.switch(0)

    ret = s.resp_entry.data
    s.resp_entry = None
    return ret

  @blocking
  def write( s, addr, data ):
    while s.req_entry is not None:
      greenlet.getcurrent().parent.switch(0)

    s.req_entry = s.create_req( 1, addr, data )

    while s.resp_entry is None:
      greenlet.getcurrent().parent.switch(0)

    s.resp_entry = None

  def construct( s, ReqType, RespType ):
    s.requester = RequesterIfc( ReqType, RespType )

    # Use create_req to handle type mismatch
    Tdata = ReqType.get_field_type('data')
    s.create_req = lambda a,b,c=0: ReqType( a, b, Tdata(int(c)) )

    s.req_entry  = None
    s.resp_entry = None

    # req path

    s.req_sent = Wire()

    @update_ff
    def up_req_sent():
      s.req_sent <<= s.requester.reqstream.val & s.requester.reqstream.rdy

    @update
    def up_clear_req():
      if s.req_sent:
        s.req_entry = None

    @update_once
    def up_send_req():
      if s.req_entry is None:
        s.requester.reqstream.val @= 0
      else:
        s.requester.reqstream.val @= 1
        s.requester.reqstream.msg @= s.req_entry

    # resp path
    @update_once
    def up_resp_rdy():
      s.requester.respstream.rdy @= (s.resp_entry is None)

    @update_once
    def up_resp_msg():
      if (s.resp_entry is None) & s.requester.respstream.val:
        s.resp_entry = clone_deepcopy( s.requester.respstream.msg )

    s.add_constraints( U( up_clear_req ) < M(s.read),
                       U( up_clear_req ) < M(s.write),

                       M( s.read )    < U( up_send_req ),
                       M( s.write )   < U( up_send_req ),

                       M( s.read )      < U( up_resp_rdy ),
                       M( s.write )     < U( up_resp_rdy ),
                       U( up_resp_rdy ) < U( up_resp_msg ) )

# max_cycles
  max_cycles = request.config.getoption("max_cycles")
  if max_cycles is not None:
    try:
      max_cycles = int(max_cycles)
    except ValueError:
      raise Exception("command line option `--max-cycles` should have integer value!")
  opts['max_cycles'] = max_cycles

  return opts

